"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63698"],{82893(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.anexo_do_ato.hash_invalido","status":422,"titulo":"O hash do anexo deve ser um SHA-256 em hexadecimal min\xfasculo"},"descricao":{"codigo":"uniplus.publicacoes.anexo_do_ato.hash_invalido","requisitos":["UNI-REQ-0154","UNI-REQ-0155"],"oQueAconteceu":["Cada anexo \xe9 provado pelo hash do arquivo, e sem ele o hash do documento principal n\xe3o prova\\nque o ato publicado \xe9 o que se registrou. O hash informado para um dos anexos n\xe3o \xe9 um\\nSHA-256 em hexadecimal min\xfasculo, com 64 caracteres. A mensagem de detalhe nomeia o anexo.\\nOs anexos s\xe3o conferidos antes de qualquer consulta ao banco, tanto na opera\xe7\xe3o\\nadministrativa de Publica\xe7\xf5es quanto no registro feito pelo m\xf3dulo dono do objeto, na mesma opera\xe7\xe3o da publica\xe7\xe3o, e a recusa nomeia o\\nprimeiro anexo com problema."],"comoResolver":["Calcule o SHA-256 do arquivo do anexo, escreva-o em hexadecimal min\xfasculo, com 64\\ncaracteres, e registre o ato de novo."],"ondeAparece":["Registro de ato normativo","Registro de ato normativo pelo m\xf3dulo dono do objeto, na mesma opera\xe7\xe3o da publica\xe7\xe3o"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Anexo do ato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);